contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 artId, address to, uint256 id, uint256 value, uint256 quantity, address minter, address ref, address verifier, bytes32 data, string calldata imageURI) public payable {
        c.pause();
        bool pausedBefore = c.paused();

        bool reverted1;
        try c.createArtFromFactory(artId) { reverted1 = false; } catch { reverted1 = true; }

        bool reverted2;
        try c.claimFromFactory(artId, minter, ref, verifier, quantity, data, imageURI) { reverted2 = false; } catch { reverted2 = true; }

        bool reverted3;
        try c.safeTransferFrom(address(this), to, id, value, "") { reverted3 = false; } catch { reverted3 = true; }

        uint256[] memory ids = new uint256[](1);
        ids[0] = id;
        uint256[] memory values = new uint256[](1);
        values[0] = value;
        bool reverted4;
        try c.safeBatchTransferFrom(address(this), to, ids, values, "") { reverted4 = false; } catch { reverted4 = true; }

        assert(pausedBefore && reverted1 && reverted2 && reverted3 && reverted4 && c.paused());
    }

    receive() external payable {}
}

