contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 credChainId, uint256 credId, string calldata verificationType, address protocolFeeDestination, address to, uint256 id, uint256 value) public {
        require(to != address(0), "to must be nonzero");

        bool pauseReverted;
        try c.pause() { pauseReverted = false; } catch { pauseReverted = true; }

        bool unPauseReverted;
        try c.unPause() { unPauseReverted = false; } catch { unPauseReverted = true; }

        bool createArtReverted;
        try c.createArtFromFactory(1) { createArtReverted = false; } catch { createArtReverted = true; }

        bool transferReverted;
        try c.safeTransferFrom(address(this), to, id, value, "") { transferReverted = false; } catch { transferReverted = true; }

        c.initialize(credChainId, credId, verificationType, protocolFeeDestination);

        bool secondInitReverted;
        try c.initialize(credChainId, credId, verificationType, protocolFeeDestination) { secondInitReverted = false; } catch { secondInitReverted = true; }

        assert(pauseReverted && unPauseReverted && createArtReverted && transferReverted && secondInitReverted);
    }
}

