contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool callPause) public payable {
        // Fresh, directly deployed implementation: it can never be the owner of itself,
        // because it sets its own owner to msg.sender during initialize.
        // Thus both pause() and unPause() from this test contract must revert.
        bool reverted;
        if (callPause) {
            try c.pause() { reverted = false; } catch { reverted = true; }
        } else {
            try c.unPause() { reverted = false; } catch { reverted = true; }
        }
        assert(reverted && c.paused() == false && c.owner() != address(this));
    }

    receive() external payable {}
}

